{
  "case_id": "xsu_sg_011_doctor_certificate",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Kernen er korrekt: lægeattest kan indhentes, og den skal beskrive funktionsevne og behov for fortsat behandling eller henvisning. Men svaret påstår, at Udbetaling Danmark kan afvise ansøgningen uden realitetsbehandling, hvis minimumskravene slet ikke er opfyldt. Det fremgår ikke af de frosne kilder. Svaret siger også, at 'supplerende lægefaglige oplysninger' kun kan indhentes 'i særlige tilfælde', og det forskyder kilden, som siger yderligere journaloplysninger i forbindelse med lægeattesten. Svaret anfører, at Udbetaling Danmark 'først forsøger at få sagen belyst yderligere', hvilket heller ikke er støttet."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: at attesten kan indhentes, når funktionsniveauet ikke kan vurderes, at attesten skal belyse funktionsevnen i forhold til den ansøgte funktionsnedsættelse, og at den skal belyse behov for fortsat behandling eller henvisning til specialist. Svaret nævner 'praktiserende læge'."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge dele af spørgsmålet: hvad Udbetaling Danmark kan gøre, og hvad lægeattesten skal beskrive."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til en identificerbar kilde, vejledning nr. 10157 af 5. oktober 2026, og bruger noteangivelser. Hovedpåstandene om lægeattesten kan føres tilbage til afsnit 5.1.2."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning VEJ nr. 10157 er en eksisterende, aktuel og autoritativ kilde inden for den frosne kildeafgrænsning og er anvendelig til spørgsmålet."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Påstanden om afvisning uden realitetsbehandling er knyttet til note 3, men afsnit 5.1.2 siger intet om afvisning. Den støttes heller ikke af de udleverede bestemmelser, hvor § 37, stk. 5 kun nævner en frist for yderligere dokumentation. Påstanden om, at Udbetaling Danmark 'først forsøger' yderligere belysning, har heller ikke støtte i passagen."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en retsvirkning, nemlig afvisning uden realitetsbehandling ved manglende minimumsdokumentation. Det har ikke støtte i kildematerialet. Svaret tilføjer også en rækkefølge, hvor man først forsøger at belyse sagen yderligere, og at afvisning 'typisk' kun er relevant ved manglende minimumsdokumentation."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bruger 'kan' for muligheden for at indhente lægeattest og fremstiller den ikke som en automatisk pligt. Fremmøde nævnes ikke, og rubrikken kræver kun forbeholdet, hvis fremmøde omtales. 'I særlige tilfælde' er bevaret for de supplerende oplysninger."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret blander to forskellige situationer: utilstrækkelig dokumentation til at vurdere funktionsniveau (lægeattest) og manglende minimumsdokumentation (afvisning). Konklusionen om, at Udbetaling Danmark 'først forsøger' yderligere belysning og kun 'typisk' afviser ved manglende minimum, følger ikke af de angivne kilder."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Modaliteten er korrekt for 'kan indhente lægeattest' og 'skal beskrive'. Svaret gør dog en skønsmulighed om afvisning til en 'kan'-hjemmel uden kildestøtte. Formuleringerne 'mest nærliggende' og 'typisk' præsenterer en praksis, som kilden ikke angiver."
    }
  },
  "xhaile_coverage": {
    "A61": {
      "label": "partial",
      "reason": "Svaret dækker, at lægeattest kan indhentes, og hvad den skal beskrive (funktionsevne, behov for behandling/henvisning). Det nævner kort yderligere journaloplysninger i særlige tilfælde. Det udelader kravet om fremmøde og udgiftsafholdelsen. Det tilføjer samtidig ustøttet indhold om afvisning."
    }
  },
  "overall_notes": "Kerneindholdet om lægeattesten er korrekt og dækker rubrikkens kritiske elementer. Svaret er dog svækket af en ikke-understøttet påstand om afvisning uden realitetsbehandling og af en ikke-understøttet beskrivelse af, hvad Udbetaling Danmark 'først' gør. Det giver fejl på de juridiske og kildebaserede kriterier trods god dækning af selve attestindholdet."
}

